import { isGameTradition, type MythologyCatalogue, type MythologyEntity } from "./mythology-map.ts";

type Story = { story: string; detail: string };
const stories: Record<string, Story> = {
  "cosmic-egg": { story: "In one Orphic telling, the cosmic egg is generated by Chronos, Time. Phanes emerges from it. A very different way to begin a divine family.", detail: "This is creation followed by emergence, rather than an ordinary birth. The account is preserved through later witnesses." },
  phanes: { story: "Phanes emerges from the cosmic egg in the Orphic material quoted by later writers. His place near the beginning is one reason there is no single Greek creation story.", detail: "These are reported Orphic traditions, rather than another chapter of Hesiod. Their sources stay separate here." },
  "chronos-hades": { story: "In Hades II, Chronos is the Titan of Time and father to Hades, Zeus and Poseidon. Melinoë is trying to stop her own grandfather.", detail: "The game puts Time and the father of the Olympian brothers in one character. In the ancient accounts on this map, Chronos and Kronos have separate entries." },
  "chronos-time": { story: "Chronos here is Time, a primordial figure in the Orphic account reported by Damascius. He generates the egg from which Phanes emerges.", detail: "This is a separate entry from Kronos the Titan. The similar names can make an already complicated family rather confusing." },
  erebus: { story: "Erebus personifies Darkness. Hesiod places him with Nyx among the children of Chaos; together they become the parents of Aether and Hemera.", detail: "Darkness, Night, Day and the bright upper air all sit on the same family branch." },
  oceanus: { story: "Oceanus is one of the Titans. With Tethys, he stands at the head of the enormous family of Oceanids and river gods.", detail: "The poem mentions thousands, even though its named lists preserve only a selection. Each named river or nymph can have a separate entry." },
  tethys: { story: "Tethys is a Titan and, with Oceanus, a parent of the Oceanids and river gods. Water becomes an enormous divine family through this branch.", detail: "Tethys the Titan is a separate figure from Thetis, the Nereid associated with Achilles." },
  nymphs: { story: "Nymphs are the many divine nature figures associated with places such as trees, rivers and springs. This is a broad category, rather than one person with a single agreed parentage.", detail: "A dotted seal represents a collective. The individual names have their own family links and source passages." },
  nereids: { story: "The Nereids are the sea nymphs born to Nereus and Doris in Hesiod. Thetis and Amphitrite are among their more familiar names.", detail: "The poem says fifty, but the transmitted list used here yields 51 distinct names. That discrepancy stays visible in the coverage notes." },
  oceanids: { story: "The Oceanids belong to the vast family of Oceanus and Tethys. Names such as Metis and Styx have important individual connections within that much larger group.", detail: "Being part of a collective does not give every member the same story. Follow the individual names to see the differences." },
  harpies: { story: "The Harpies are winged beings born to Thaumas and Electra in Hesiod. Other tellings add different names to the family.", detail: "They have a genealogy and individual names, rather than being only a generic monster category." },
  moirai: { story: "The Moirai are the Fates: Clotho, Lachesis and Atropos. They are one of the clearest examples of a collective with individually named members.", detail: "Even Hesiod preserves different origins for the Fates, connecting them with Nyx in one passage and Zeus and Themis in another." },
  muses: { story: "The Muses are the nine daughters of Zeus and Mnemosyne in Hesiod. They connect divine genealogy with poetry and song.", detail: "Mnemosyne is Memory. Putting Memory beside the goddesses of poetry is a connection worth following." },
  "persephone-mortal-father-game": { story: "The game’s Persephone speaks of a mortal father, but the checked dialogue does not give him a name. This entry keeps him anonymous instead of borrowing a name from ancient genealogy.", detail: "This is a game-continuity difference. The ancient account naming Zeus remains in the other graph." },
  chaos: { story: "In Hesiod, the story opens with Chaos: a primordial opening, before the familiar divine family takes shape. Night and Darkness emerge from it. In Hades, Chaos remembers a world before Time and calls Nyx their child.", detail: "Coming first does not make Chaos everybody’s parent. Other ancient accounts begin differently." },
  gaia: { story: "Gaia is Earth herself, both the ground beneath the stories and a divine ancestor. She bears Sky and Sea and stands near the beginning of many family lines.", detail: "A personification can still be a god. The categories overlap from the very beginning." },
  uranus: { story: "Uranus is the Sky, born from Gaia in Hesiod. Their descendants include the Titans, placing him a generation before Kronos and Rhea.", detail: "Aphrodite’s sea-foam origin also connects to Uranus. Emergence is shown separately from ordinary birth." },
  kronos: { story: "Kronos belongs to the Titans and, with Rhea, fathers the generation of Zeus, Poseidon and Hades. Family succession is rather dramatic in this part of the mythology.", detail: "Kronos the Titan and Chronos as Time have separate entries here. Similar names, different source traditions." },
  rhea: { story: "Rhea is a Titan and the mother of the six divine siblings named by Hesiod: Hestia, Demeter, Hera, Hades, Poseidon and Zeus.", detail: "Her branch is a good place to see how closely connected the familiar Olympian names are." },
  hyperion: { story: "Hyperion is one of the Titans. In Hesiod, his children with Theia include Helios, Selene and Eos: Sun, Moon and Dawn.", detail: "Hades dialogue gives him another family connection: Hera, Hestia and Demeter call him their father." },
  zeus: { story: "Zeus is the Olympian ruler associated with the sky and thunder. In Hesiod, he is a son of Kronos and Rhea and a parent in many of the later divine families.", detail: "Recognise the thunderbolt. Then follow his children and see how quickly a simple family tree stops being simple." },
  hera: { story: "Hera is the queen of the gods, associated with marriage and her relationship with Zeus. She is much more than a supporting character in somebody else’s family drama.", detail: "Hesiod places her under Kronos and Rhea. The Hades dialogue instead names Hyperion as her father." },
  poseidon: { story: "Poseidon rules the sea and is also associated with earthquakes. In Hesiod’s genealogy he is a brother of Zeus and Hades.", detail: "His trident makes him easy to spot. The sea itself, its primordial beings and its many nymphs have their own entries too." },
  hades: { story: "Hades rules the realm of the dead. He belongs to the same divine generation as Zeus and Poseidon, but his stories lead into a different part of the world.", detail: "Hades rules the dead. Thanatos is Death itself. Same neighbourhood, very different job descriptions." },
  demeter: { story: "Demeter is associated with grain, harvest and the growing world. She is Persephone’s mother, which places her at the centre of one of the mythology’s most important family relationships.", detail: "Hesiod names Kronos and Rhea as her parents. Hades dialogue names Hyperion and Theia." },
  hestia: { story: "Hestia is the goddess of the hearth and the shared fire of a household. Her domain is quieter than thunder or war, but it belongs at the centre of everyday life.", detail: "Her ancient family includes Kronos and Rhea. Hades dialogue instead groups her with Hyperion’s daughters." },
  athena: { story: "Athena brings together wisdom, skilled crafts and war. The ancient accounts connect her birth with Zeus and Metis rather than giving her an ordinary two-parent birth story.", detail: "Look for the owl. Her broad range is a useful reminder that a deity rarely fits one neat god-of-something label." },
  apollo: { story: "Apollo is associated with music and prophecy. In Hesiod, Zeus and Leto are his parents, and Artemis is his sister.", detail: "His lyre is the visual cue here. Helios, the Sun, remains a separate figure rather than being silently folded into Apollo." },
  artemis: { story: "Artemis belongs to the wild world of hunting and animals. She and Apollo share Zeus and Leto as parents in the cited genealogy.", detail: "Her bow distinguishes her from Selene, the Moon. The two remain separate names in this catalogue." },
  ares: { story: "Ares is associated with war and battle. Hesiod names him among the children of Zeus and Hera.", detail: "A shield and spear identify his seal. Compare his place in battle with Athena’s rather different range of war, wisdom and craft." },
  aphrodite: { story: "Aphrodite is the goddess associated with love and desire. Even her beginnings depend on which ancient telling you follow.", detail: "Hesiod describes a sea-foam emergence connected to Uranus. Homer calls her a daughter of Zeus and Dione. These are separate accounts." },
  hermes: { story: "Hermes is a traveller, messenger and trickster, with Zeus and Maia as his parents in Hesiod. His stories move easily between different parts of the divine world.", detail: "The winged herald’s staff is his cue. Maia also opens another branch through Atlas and the Pleiades." },
  dionysus: { story: "Dionysus is associated with wine and revelry. Hesiod names Zeus and Semele as his parents, while other traditions preserve further divine connections.", detail: "Grapes make his seal easy to recognise. Keep an eye on the sources when his story overlaps other underworld traditions." },
  hephaestus: { story: "Hephaestus is the divine smith, associated with metalworking and skilled craft. His family story is one of the places where ancient authors differ.", detail: "Hesiod gives Hera a birth without a partner. Other accounts involve Zeus too, so the two parent sets stay separate." },
  persephone: { story: "Persephone is Demeter’s daughter and queen of the Underworld. Her place between divine families makes her a particularly interesting name to follow in both the myths and the games.", detail: "Her family changes between ancient accounts and Hades continuity. The game’s more revealing origin details remain covered until you choose to uncover them." },
  nyx: { story: "Nyx is Night herself, a primordial divine figure. Her children include beings associated with Sleep, Death, Doom and Strife.", detail: "She is not simply a goddess with a night shift. Night is what she represents, which is why divine categories can overlap." },
  hecate: { story: "Hecate is associated with magic and crossroads. Hesiod names Asteria and Perses as her parents.", detail: "In Hades II she cares for and trains Melinoë. That is a mentorship connection, not a claim that she is Melinoë’s biological mother." },
  melinoe: { story: "Melinoë is an underworld deity invoked in an Orphic hymn and the protagonist reimagined for Hades II. She is a perfect starting point for comparing an ancient figure with a game adaptation.", detail: "The Orphic hymn names Zeus and Persephone. Hades II gives her Hades and Persephone. Same name, a different branch." },
  zagreus: { story: "Zagreus spends the first Hades trying to escape the Underworld and make sense of his family. In Hades II, his sister Melinoë takes the lead.", detail: "Hades II shifts from a brother trying to get out of the Underworld to a sister trying to get her family back." },
  charon: { story: "Charon ferries the dead through the Underworld. His work makes him familiar even when the older sources give us little about his family.", detail: "No ancient parents are established in the passages checked here. Hades II dialogue names Nyx as his mother." },
  thanatos: { story: "Thanatos personifies Death. He belongs among the children of Night in Hesiod and appears in the first Hades.", detail: "He is distinct from Hades, the ruler of the dead. Following both names makes that difference much easier to remember." },
  hypnos: { story: "Hypnos personifies Sleep and belongs to Nyx’s family. His connection with Thanatos puts Sleep and Death on the same remarkable branch.", detail: "The sleeping eye and wing are navigation cues. A personified experience can have a family and a personality in these stories." },
  moros: { story: "Moros personifies Doom and is one of Nyx’s children in Hesiod. Hades II turns that ominous name into someone you can actually get to know.", detail: "Doom, Sleep and Death being relatives is quite a family introduction." },
  nemesis: { story: "Nemesis is associated with retribution and the correction of excess. She is another figure whose abstract role becomes a strong personality in Hades II.", detail: "Her scales are a useful visual cue. The game’s character introduction calls her Retribution Incarnate." },
  eris: { story: "Eris personifies Strife and belongs to Nyx’s family in Hesiod. She makes conflict a character you can encounter rather than just a thing that happens.", detail: "She is another reason the boundary between a god and a personification does not stay neat for very long." },
  "dora-game": { story: "Dora is the friendly shade who shares Melinoë’s tent at the Crossroads. Her conversations gradually suggest that there is more behind her name and personality.", detail: "Her identity connection stays hidden here until you uncover the game spoilers. The seal only shows a shade." },
  "dusa-game": { story: "Dusa is the floating Gorgon custodian in the first Hades. A minor encounter can still make the Underworld feel like a place full of individual lives.", detail: "This entry keeps her game identity separate rather than automatically assigning her another Gorgon’s ancient biography." },
};

export function mythologyStory(entity: MythologyEntity, catalogue: MythologyCatalogue): Story {
  if (stories[entity.id]) return stories[entity.id];
  const byId = new Map(catalogue.entities.map((item) => [item.id, item]));
  const origin = catalogue.lineages.filter((claim) => claim.child === entity.id && !claim.spoiler && !isGameTradition(claim.tradition)).sort((a, b) => b.parents.length - a.parents.length)[0];
  const group = catalogue.relationships.find((claim) => claim.from === entity.id && claim.type === "member_of" && !claim.spoiler);
  const meaningful = !/appears in the cited|in the cited tradition\.?$|in the cited account\.?$/i.test(entity.summary);
  const relation = origin?.mode === "creation" ? "is generated by" : origin?.mode === "emergence" ? "emerges from" : "is named as a child of";
  const family = origin ? `${entity.name} ${relation} ${origin.parents.map((id) => byId.get(id)?.name || id).join(" and ")} in ${origin.tradition}.` : "";
  const membership = group ? `This entry places ${entity.name} among the ${byId.get(group.to)?.name || group.to}.` : "";
  const role = entity.domains.length ? `${entity.name} is associated with ${entity.domains.join(", ")}.` : `${entity.name} appears in the source as ${entity.kind === "collective" ? "a collective group" : "a named figure"}.`;
  const child = catalogue.lineages.find((claim) => claim.parents.includes(entity.id) && !claim.spoiler && !isGameTradition(claim.tradition));
  const source = catalogue.sources.find((item) => item.id === entity.sourceRefs[0]?.sourceId);
  const continuation = child ? `${byId.get(child.child)?.name || child.child} continues this family branch.` : source ? `This entry follows ${source.author}, ${source.title}.` : role;
  return {
    story: [meaningful ? entity.summary : membership || role, family || continuation].filter(Boolean).join(" "),
    detail: entity.kind === "collective" ? "This seal represents a group. The individual members have their own entries where the sources name them."
      : membership || (origin ? "The cited entry preserves a name and a family connection. The source list below is the place to explore further." : "The checked sources do not establish parents for this entry. An unknown origin stays unknown here."),
  };
}
